--
-- Structure de la vue `latest_quotes`
--
DROP TABLE IF EXISTS `latest_quotes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `latest_quotes`  AS SELECT `c`.`id` AS `company_id`, `c`.`symbol` AS `symbol`, `c`.`name` AS `name`, `s`.`name` AS `sector`, `sq`.`trading_date` AS `trading_date`, `sq`.`open_price` AS `open_price`, `sq`.`close_price` AS `close_price`, `sq`.`high_price` AS `high_price`, `sq`.`low_price` AS `low_price`, `sq`.`previous_close` AS `previous_close`, `sq`.`volume` AS `volume`, `sq`.`variation_percent` AS `variation_percent`, `sq`.`turnover` AS `turnover` FROM ((`companies` `c` left join `sectors` `s` on((`c`.`sector_id` = `s`.`id`))) left join `stock_quotes` `sq` on((`c`.`id` = `sq`.`company_id`))) WHERE ((`sq`.`trading_date` = (select max(`stock_quotes`.`trading_date`) from `stock_quotes` where (`stock_quotes`.`company_id` = `c`.`id`))) AND (`c`.`active` = 1)) ORDER BY `c`.`symbol` ASC  ;

-- --------------------------------------------------------

--
-- Structure de la vue `top_gainers`
--
DROP TABLE IF EXISTS `top_gainers`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `top_gainers`  AS SELECT `c`.`symbol` AS `symbol`, `c`.`name` AS `name`, `sq`.`close_price` AS `close_price`, `sq`.`variation_percent` AS `variation_percent`, `sq`.`volume` AS `volume`, `sq`.`trading_date` AS `trading_date` FROM (`stock_quotes` `sq` join `companies` `c` on((`sq`.`company_id` = `c`.`id`))) WHERE ((`sq`.`trading_date` = (select max(`stock_quotes`.`trading_date`) from `stock_quotes`)) AND (`sq`.`variation_percent` > 0) AND (`c`.`active` = 1)) ORDER BY `sq`.`variation_percent` DESC LIMIT 0, 1010  ;

-- --------------------------------------------------------

--
-- Structure de la vue `top_losers`
--
DROP TABLE IF EXISTS `top_losers`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `top_losers`  AS SELECT `c`.`symbol` AS `symbol`, `c`.`name` AS `name`, `sq`.`close_price` AS `close_price`, `sq`.`variation_percent` AS `variation_percent`, `sq`.`volume` AS `volume`, `sq`.`trading_date` AS `trading_date` FROM (`stock_quotes` `sq` join `companies` `c` on((`sq`.`company_id` = `c`.`id`))) WHERE ((`sq`.`trading_date` = (select max(`stock_quotes`.`trading_date`) from `stock_quotes`)) AND (`sq`.`variation_percent` < 0) AND (`c`.`active` = 1)) ORDER BY `sq`.`variation_percent` ASC LIMIT 0, 1010  ;

-- --------------------------------------------------------

--
-- Structure de la vue `volume_leaders`
--
DROP TABLE IF EXISTS `volume_leaders`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `volume_leaders`  AS SELECT `c`.`symbol` AS `symbol`, `c`.`name` AS `name`, `sq`.`close_price` AS `close_price`, `sq`.`volume` AS `volume`, `sq`.`turnover` AS `turnover`, `sq`.`variation_percent` AS `variation_percent`, `sq`.`trading_date` AS `trading_date` FROM (`stock_quotes` `sq` join `companies` `c` on((`sq`.`company_id` = `c`.`id`))) WHERE ((`sq`.`trading_date` = (select max(`stock_quotes`.`trading_date`) from `stock_quotes`)) AND (`c`.`active` = 1)) ORDER BY `sq`.`volume` DESC LIMIT 0, 1010  ;

